 --font-family:'Segoe UI',Arial,sans-serif; --font-size-header:26px; --font-size-paragraph:14px; --font-size-label:14px; --font-size-input:16px; --font-size-error:12px;
 --color-background:#edf5f1; --color-card-bg:#ffffff; --color-card-border:#dce9e2; --color-card-shadow:#123c3410;
 --color-header:#133d32; --color-header-subtext:#587168; --color-label:#244c3f; --color-link:#008a59;
 --color-input-bg:#fbfdfb; --color-input-text:#173c34; --color-input-border:#cdded4; --color-focus-border:#008a59;
 --color-submit-btn-bg:#00d78b; --color-submit-btn-text:#003c28; --color-error:#b42336; --color-required:#008a59;
 --border-radius-card:20px; --border-radius-input:9px; --padding-card:30px; --padding-form-input:13px;
 --container-width:650px; --submit-btn-height:51px; --box-shadow-card:0 10px 30px #123c3410;
}
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; padding:24px 16px; background:#edf5f1; color:#173c34; }
.container { width:100%; max-width:650px; margin:0 auto; padding:0; }
.card { background:#fff; border:1px solid #dce9e2; border-radius:20px; padding:30px 34px; box-shadow:0 10px 30px #123c3410; overflow:hidden; }
#n8n-form::before, #submitted-form::before { content:''; display:block; width:calc(100% + 68px); aspect-ratio:2048 / 683; margin:-30px -34px 28px; border-radius:19px 19px 0 0; background:#002824 url('https://example.com/imagens/banner.png') center / 100% 100% no-repeat; }
.form-header { display:block; text-align:center; margin-bottom:26px; }
.form-header h1 { color:#133d32; font-size:26px; font-weight:650; letter-spacing:-.6px; line-height:1.2; margin:0 0 10px; }
.form-header p { display:block; color:#587168; font-size:14px; line-height:1.6; margin:0; padding:0; }
.inputs-wrapper { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px 18px; padding:0 0 8px; }
.inputs-wrapper > .form-group:first-child, .inputs-wrapper > .form-group:nth-child(n+6), .inputs-wrapper > .form-group.html, .inputs-wrapper > div:has(input[type=checkbox]) { grid-column:1 / -1; }
.form-group { min-width:0; margin-bottom:0; }
form label { display:block; color:#244c3f; font-weight:600; font-size:14px; line-height:1.5; }
form .form-input { width:100%; min-height:48px; padding:12px 13px; border:1px solid #cdded4; border-radius:9px; background:#fbfdfb; color:#173c34; font-size:16px; }
form .form-input::placeholder { color:#788b81; }
form .form-input:focus { border-color:#008a59; outline:2px solid #008a59; outline-offset:2px; box-shadow:none; }
.form-group.html { margin-top:14px; padding:18px 20px; background:#f0f8f3; border-radius:12px; color:#355f4c; font-size:13px; line-height:1.6; }
.form-group.html h3 { font-size:14px; font-weight:600; color:#355f4c; margin:0 0 10px; }
.form-group.html p { margin:10px 0 0; }
.multiselect { border:0 !important; padding:0 !important; background:transparent !important; }
.multiselect-option { padding:8px 0 !important; background:transparent !important; color:#405f51; }
.multiselect-option label, .multiselect-option span { font-weight:400; font-size:13px; line-height:1.6; }
input[type=checkbox] { accent-color:#008b59; min-width:19px; min-height:19px; }
.error-hidden { min-height:18px; font-size:12px; }
#submit-btn { display:block; width:100%; min-height:51px; border:0; border-radius:10px; background:#00d78b; color:#003c28; font-size:15px; font-weight:650; margin-top:6px; }
#submit-btn:hover { background:#00c980; }
#submit-btn:focus-visible { outline:3px solid #008a59; outline-offset:3px; }
#submit-btn:disabled { opacity:.6; }
#n8n-form::after { content:'Participação no evento · Empresa Exemplo'; display:block; text-align:center; font-size:12px; color:#627c6e; margin-top:13px; }
#submitted-form { text-align:center; }
#submitted-header { color:#008a59; }
#submitted-content { color:#244c3f; line-height:1.6; overflow-wrap:anywhere; }
a { color:#008a59; overflow-wrap:anywhere; }
@media(max-width:480px) { body { padding:14px 9px; } .card { padding:24px 18px; } #n8n-form::before, #submitted-form::before { width:calc(100% + 36px); margin:-24px -18px 24px; } .inputs-wrapper { grid-template-columns:1fr; gap:4px; } .form-header h1 { font-size:23px; } }

/* Aviso recolhível: controle visual separado do consentimento. */
.inputs-wrapper > div:has(input[value="Privacidade e uso dos seus dados"]) { grid-column:1/-1; background:#f0f8f3; border-radius:12px; padding:18px 20px; margin-top:14px; }
.inputs-wrapper > div:has(input[value="Privacidade e uso dos seus dados"]) > label,
.inputs-wrapper > div:has(input[value="Privacidade e uso dos seus dados"]) > .error-hidden { display:none; }
input[value="Privacidade e uso dos seus dados"] { position:absolute; opacity:0; width:1px; height:1px; min-width:0; min-height:0; }
input[value="Privacidade e uso dos seus dados"] + label { display:block; width:100%; cursor:pointer; color:#355f4c; font-weight:600; }
input[value="Privacidade e uso dos seus dados"] + label::before { content:'▶'; margin-right:8px; }
input[value="Privacidade e uso dos seus dados"]:checked + label::before { content:'▼'; }
input[value="Privacidade e uso dos seus dados"]:focus-visible + label { outline:2px solid #008a59; outline-offset:4px; }
.inputs-wrapper > div:has(input[value="Privacidade e uso dos seus dados"]) + .form-group.html { display:none; }
.inputs-wrapper > div:has(input[value="Privacidade e uso dos seus dados"]:checked) + .form-group.html { display:block; margin-top:0; }
/* Três logos: Parceiro 1 | Empresa | Parceiro 2 */
#n8n-form::before,
#submitted-form::before {
  content: "";
  display: block;
  width: 100%;
  height: 120px;
  aspect-ratio: auto;
  margin: 0 0 28px;
  border-radius: 0;
  border-bottom: 3px solid #00d78b;

  background-color: #ffffff;
  background-image:
    url("https://example.com/imagens/logo-parceiro-1.png"),
