assignments.value:
={{ (() => {
  const email = v => String(v ?? '').trim().toLowerCase();

  const telefone = v => {
    const n = String(v ?? '').replace(/\D/g, '');
    return (n.length === 12 || n.length === 13) &&
      n.startsWith('55') ? n.slice(2) : n;
  };

  const vencedores = $('Ler Vencedores Anteriores')
    .all()
    .map(item => item.json)
    .filter(p =>
      String(p.Status ?? '').trim().toUpperCase() === 'VENCEDOR'
    );

  const emailsPremiados = new Set(
    vencedores.map(p => email(p['E-mail'])).filter(Boolean)
  );

  const telefonesPremiados = new Set(
    vencedores.map(p => telefone(p.Telefone)).filter(Boolean)
  );

  const emailsIncluidos = new Set();
  const telefonesIncluidos = new Set();
  const elegiveis = [];

  for (const item of $('Ler Participantes').all()) {
    const p = item.json;
    const nome = String(p.Nome ?? '').trim();
    const e = email(p['E-mail']);
    const t = telefone(p.Telefone);

    if (
      nome.length < 2 ||
      !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e) ||
      !/^\d{10,11}$/.test(t)
    ) continue;

    if (
      emailsPremiados.has(e) ||
      telefonesPremiados.has(t) ||
      emailsIncluidos.has(e) ||
      telefonesIncluidos.has(t)
    ) continue;

    emailsIncluidos.add(e);
    telefonesIncluidos.add(t);

    elegiveis.push({
      Nome: nome,
      'E-mail': e,
      Telefone: t,
      Cargo: String(p.Cargo ?? '').trim(),
      Empresa: String(p.Empresa ?? '').trim()
    });
  }

  return elegiveis;
})() }}

