      margin: 24px auto;
    }
  </style>
</head>
<body>
  <main>
    <div class="logos">
      <img src="https://example.com/imagens/logo-parceiro-1.png"
           alt="Parceiro 1">
      <img class="empresa" src="https://example.com/imagens/logo-empresa.png"
           alt="Empresa Exemplo">
      <img src="https://example.com/imagens/logo-parceiro-2.png"
           alt="Parceiro 2">
    </div>

    <h1>Cadastre-se e participe!</h1>
    <p>Aponte a câmera do celular para o QR Code<br>
       e preencha o formulário.</p>

    <img
      class="qr"
      src="https://api.qrserver.com/v1/create-qr-code/?size=600x600&amp;qzone=4&amp;data=${encodeURIComponent($json.urlCadastro)}"
