parameters.completionMessage:
={{ (() => {
  const p = $('Preparar Resultado').first().json;

  const escapar = v => String(v ?? '').replace(
    /[&<>"']/g,
    c => ({
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#39;'
    }[c])
  );

  return '<strong>' + escapar(p.Nome) + '</strong>'
    + '<br>Empresa: ' + escapar(p.Empresa || 'Não informada')
    + '<br><br>Resultado registrado com sucesso.'
    + '<br>Este participante foi excluído dos próximos sorteios.'
    + '<br><br>Abra novamente o painel para realizar outro sorteio.';
})() }}

